def _pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
    value: dict[str, Any] = {}
    for key, item in items:
        if key in value:
            raise ValueError("NATIVE_CASE_REGISTRY_DUPLICATE_KEY")
        value[key] = item
    return value


def _bounded_decompress(raw: bytes, limit: int = MAX_DECOMPRESSED_PAYLOAD_BYTES) -> bytes:
    if not raw or len(raw) > MAX_COMPRESSED_PAYLOAD_BYTES:
        raise ValueError("NATIVE_CASE_REGISTRY_CAPACITY_EXHAUSTED")
    decoder = zlib.decompressobj()
    output = bytearray()
    offset = 0
    try:
        while offset < len(raw):
            chunk = raw[offset:offset + 64 * 1024]
            offset += len(chunk)
            while chunk:
                remaining = limit - len(output)
                if remaining <= 0:
                    raise ValueError("NATIVE_CASE_REGISTRY_CAPACITY_EXHAUSTED")
                output.extend(decoder.decompress(chunk, remaining + 1))
                if len(output) > limit:
                    raise ValueError("NATIVE_CASE_REGISTRY_CAPACITY_EXHAUSTED")
                chunk = decoder.unconsumed_tail
        remaining = limit - len(output)
        output.extend(decoder.flush(remaining + 1))
    except zlib.error as exc:
        raise ValueError("NATIVE_CASE_REGISTRY_INVALID") from exc
    if len(output) > limit:
        raise ValueError("NATIVE_CASE_REGISTRY_CAPACITY_EXHAUSTED")
    if not decoder.eof or decoder.unused_data:
        raise ValueError("NATIVE_CASE_REGISTRY_INVALID")
    return bytes(output)


def _entry_shape_ok(identifier: Any, item: Any) -> bool:
    return (
        type(identifier) is str
        and bool(identifier)
        and type(item) is dict
        and set(item) == {
            "checking_mechanism", "request", "policy", "evidence_base64",
        }
        and type(item["checking_mechanism"]) is str
        and bool(item["checking_mechanism"])
        and type(item["request"]) is dict
        and type(item["policy"]) is dict
        and type(item["evidence_base64"]) is str
    )


def _ledger_rows() -> dict[str, dict[str, Any]]:
    """Decode and verify the source-review ledger against its bound digest."""

    if not _LEDGER_B85 or len(_LEDGER_B85) > MAX_ENCODED_PAYLOAD_BYTES:
        raise ValueError("NATIVE_CASE_SOURCE_REVIEW_CAPACITY_EXHAUSTED")
    try:
        raw = _bounded_decompress(
            base64.b85decode(_LEDGER_B85), MAX_LEDGER_BYTES
        )
        ledger = json.loads(raw.decode("utf-8"), object_pairs_hook=_pairs)
    except (binascii.Error, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("NATIVE_CASE_SOURCE_REVIEW_INVALID") from exc
    if (
        type(ledger) is not dict
        or ledger.get("schema_version") != SOURCE_REVIEW_SCHEMA
        or core_obligation_union.bytes_digest(raw) != SOURCE_REVIEW_DIGEST
        or core_obligation_union.canonical_bytes(ledger) != raw
        or type(ledger.get("rows")) is not list
        or len(ledger["rows"]) != SOURCE_REVIEW_ROW_COUNT
        or ledger.get("reviewed_prior_baseline_digest")
            != REVIEWED_PRIOR_BASELINE_DIGEST
    ):
        raise ValueError("NATIVE_CASE_SOURCE_REVIEW_DIFFERS")
    rows: dict[str, dict[str, Any]] = {}
    for row in ledger["rows"]:
        if (
            type(row) is not dict
            or type(row.get("identifier")) is not str
            or row["identifier"] in rows
        ):
            raise ValueError("NATIVE_CASE_SOURCE_REVIEW_DIFFERS")
        rows[row["identifier"]] = row
    accepted = {
        identifier for identifier, row in rows.items()
        if row.get("disposition") == "ACCEPT_REPIN"
    }
    if accepted != SOURCE_REVIEW_ACCEPTED_IDENTIFIERS:
        raise ValueError("NATIVE_CASE_SOURCE_REVIEW_DIFFERS")
    return rows


def installed_source_review() -> list[dict[str, Any]]:
    """Return the verified ledger rows in identifier order."""

    rows = _ledger_rows()
    return [rows[identifier] for identifier in sorted(rows)]


def installed_case_inputs() -> dict[str, dict[str, Any]]:
    from verifier.domains.contracts import current_object_routes

    if not _PAYLOAD_B85 or len(_PAYLOAD_B85) > MAX_ENCODED_PAYLOAD_BYTES:
        raise ValueError("NATIVE_CASE_REGISTRY_CAPACITY_EXHAUSTED")
    try:
        compressed = base64.b85decode(_PAYLOAD_B85)
        raw = _bounded_decompress(compressed)
        value = json.loads(raw.decode("utf-8"), object_pairs_hook=_pairs)
    except (binascii.Error, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("NATIVE_CASE_REGISTRY_INVALID") from exc
    if (
        type(value) is not dict
        or len(value) != CASE_REGISTRY_ENTRY_COUNT
        or json.dumps(
            value, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        ).encode("utf-8") != raw
        or not all(_entry_shape_ok(identifier, item)
                   for identifier, item in value.items())
    ):
        raise ValueError("NATIVE_CASE_REGISTRY_INVALID")
    if core_obligation_union.bytes_digest(raw) != CASE_REGISTRY_DIGEST:
        raise ValueError("NATIVE_CASE_REGISTRY_DIGEST_DIFFERS")
    patch = self_polish_native_sim_case_patch.installed_case_patch(raw)
    if set(patch) - set(value):
        raise ValueError("NATIVE_CASE_PATCH_DENOMINATOR_DIFFERS")
    value.update(patch)
    if not all(_entry_shape_ok(identifier, item)
               for identifier, item in value.items()):
        raise ValueError("NATIVE_CASE_PATCH_INVALID")
    rows = _ledger_rows()
    if set(rows) != set(value):
        raise ValueError("NATIVE_CASE_SOURCE_REVIEW_DIFFERS")
    for identifier, item in value.items():
        row = rows[identifier]
        _, coordinate = identifier.split(":", 1)
        if item["checking_mechanism"] != row["checking_mechanism"]:
            raise ValueError("NATIVE_CASE_MECHANISM_DIFFERS")
        if item["request"].get("coordinate") != coordinate:
            raise ValueError("NATIVE_CASE_COORDINATE_DIFFERS")
        module = current_object_routes.registered_mechanism_module(
            item["checking_mechanism"]
        )
        live = module.mechanism_digest()
        if item["policy"].get("mechanism_digest") != live:
            raise ValueError("NATIVE_CASE_POLICY_STALE")
        if item["request"].get("policy_digest") != core_obligation_union.value_digest(
                item["policy"]):
            raise ValueError("NATIVE_CASE_POLICY_BINDING_DIFFERS")
        if row["current_policy_mechanism_digest"] != live:
            raise ValueError("NATIVE_CASE_SOURCE_REVIEW_STALE")
        if row["request_digest"] != core_obligation_union.value_digest(
                item["request"]):
            raise ValueError("NATIVE_CASE_REQUEST_DIFFERS")
        policy_digest = core_obligation_union.value_digest(item["policy"])
        evidence_digest = core_obligation_union.bytes_digest(
            base64.b64decode(item["evidence_base64"], validate=True)
        )
        if row.get("policy_digest") != policy_digest:
            raise ValueError("NATIVE_CASE_POLICY_DIGEST_DIFFERS")
        if row.get("evidence_digest") != evidence_digest:
            raise ValueError("NATIVE_CASE_EVIDENCE_DIGEST_DIFFERS")
        if row.get("case_digest") != core_obligation_union.value_digest({
                "checking_mechanism": item["checking_mechanism"],
                "evidence_digest": evidence_digest,
                "policy_digest": policy_digest,
                "request_digest": row["request_digest"],
                }):
            raise ValueError("NATIVE_CASE_CASE_DIGEST_DIFFERS")
        if row.get("intended_negative_refusal_codes") != [
                NEGATIVE_REFUSAL_CODES[identifier]]:
            raise ValueError("NATIVE_CASE_REFUSAL_CODES_DIFFER")
        triad_cases = row.get("triad_cases")
        if type(triad_cases) is not dict or set(triad_cases) != {
                "POSITIVE", "NEGATIVE", "UNKNOWN"}:
            raise ValueError("NATIVE_CASE_TRIAD_BINDING_DIFFERS")
        for case_kind, binding in triad_cases.items():
            if (
                type(binding) is not dict
                or binding.get("case_kind") != case_kind
                or binding.get("checking_mechanism")
                    != item["checking_mechanism"]
                or binding.get("policy_digest") != policy_digest
                or binding.get("case_digest")
                    != core_obligation_union.value_digest({
                        key: binding.get(key) for key in (
                            "case_kind", "checking_mechanism",
                            "evidence_digest", "expected_native_status",
                            "intended_refusal_codes", "policy_digest",
                            "request_digest",
                        )
                    })
            ):
                raise ValueError("NATIVE_CASE_TRIAD_BINDING_DIFFERS")
    return value


__all__ = [
    "CASE_REGISTRY_DIGEST", "CASE_REGISTRY_ENTRY_COUNT",
    "CASE_REGISTRY_SCHEMA", "MAX_COMPRESSED_PAYLOAD_BYTES",
    "MAX_DECOMPRESSED_PAYLOAD_BYTES", "MAX_ENCODED_PAYLOAD_BYTES",
    "NEGATIVE_REFUSAL_CODES", "SOURCE_REVIEW_DIGEST", "SOURCE_REVIEW_SCHEMA",
    "REVIEWED_PRIOR_BASELINE_DIGEST", "SOURCE_REVIEW_ACCEPTED_IDENTIFIERS",
    "installed_case_inputs", "installed_source_review",
]
